  'settings.layoutsHint':
    'Dónde aparecen los campos en los formularios de crear, editar y ver, por tipo de ticket.',
  'admin.sets.rulesAndLayouts':
    'Las reglas de campos deciden si un campo es obligatorio, está oculto o tiene texto de ayuda. Dónde aparecen los campos, y en qué orden, lo deciden los diseños: un campo oculto nunca aparece, aunque un diseño lo coloque, y uno obligatorio siempre aparece.',
  'admin.sets.layoutsLink': 'Organiza los formularios en Conjuntos de diseños.',
  'layouts.title': 'Conjuntos de diseños',
  'layouts.purpose':
    'Organiza dónde aparecen los campos en los formularios de crear, editar y ver, para todos los tipos de ticket o para uno.',
  'layouts.about':
    'Un conjunto de diseños guarda un diseño por formulario: crear, editar y ver, para todos los tipos de ticket o para un tipo. Cada track nombra el conjunto de diseños que usa. Un formulario sin diseño propio usa el de todos los tipos, y sin ninguno muestra todos los campos en una pestaña. Arrastra campos de la lista a las secciones de una pestaña, o pulsa un asa para abrir su menú, o mantén Alt y usa las flechas. La vista previa muestra el formulario tal como lo dará el servidor, con las reglas de campos.',
  'layouts.combine':
    'Los diseños deciden dónde aparecen los campos y en qué orden. Las reglas de campos deciden si un campo es obligatorio, está oculto o tiene texto de ayuda: un campo oculto nunca aparece, aunque un diseño lo coloque, y uno obligatorio siempre aparece, tras los colocados cuando un diseño lo deja fuera.',
  'layouts.fieldRulesLink': 'Las reglas de campos están en Conjuntos de configuración.',
